-- Server-owned quiz questions and one bounded session per account.
create table app_private.quiz_questions (
 id text primary key, mode text not null check(mode in ('car','bike')),
 body jsonb not null check(jsonb_typeof(body->'o')='array')
);
create table app_private.quiz_sessions (
 user_id uuid primary key references auth.users(id) on delete cascade,
 id uuid not null unique default gen_random_uuid(),
 questions jsonb not null, responses jsonb not null default '[]',
 score integer not null default 0 check(score between 0 and 10),
 created_at timestamptz not null default now()
);
alter table app_private.quiz_questions enable row level security;
alter table app_private.quiz_sessions enable row level security;
revoke all on app_private.quiz_questions, app_private.quiz_sessions from public, anon, authenticated;

insert into app_private.quiz_questions(id,mode,body)
select item->>'id',item->>'mode',item-'mode'
from jsonb_array_elements($bank$[{"a":0,"e":"2026年9月1日から、主に中央線等がない生活道路では自動車の法定速度が原則30km/hになりました。","id":"car01","mode":"car","o":["30km/h","40km/h","60km/h"],"q":"2026年9月1日から、中央線や車両通行帯がない生活道路の自動車の法定速度は原則何km/h？"},{"a":2,"e":"中央線や車両通行帯がある一般道路などは、今回の生活道路30km/h化の対象外で、法定速度は引き続き60km/hです。","id":"car02","mode":"car","o":["30km/h","50km/h","60km/h"],"q":"2026年9月1日の改正後も、中央線や車両通行帯がある一般道路の法定速度は原則何km/h？"},{"a":1,"e":"道路標識・道路標示で最高速度が指定されている場合は、その指定速度が最高速度になります。","id":"car03","mode":"car","o":["30km/h","40km/h","60km/h"],"q":"法定速度30km/hの生活道路に「最高速度40」の標識がある場合の最高速度は？"},{"a":1,"e":"すべての道路が30km/hになったわけではなく、主に中央線等がない生活道路が対象です。","id":"car04","mode":"car","o":["はい、すべて30km/h","いいえ、対象は主に中央線等がない生活道路","夜間だけ30km/h"],"q":"2026年9月1日の改正で、すべての一般道路が30km/hになった？"},{"a":1,"e":"最高速度以内でも、道路や交通状況、天候、視界などに応じて安全な速度で運転する必要があります。","id":"car05","mode":"car","o":["はい","いいえ、道路・交通・天候等に応じ安全な速度が必要","雨の日だけ別"],"q":"生活道路で最高速度の標識がない場合、速度だけ守れば常に安全運転義務を果たせる？"},{"a":0,"e":"青地に赤い縁と赤い斜線1本の円形標識は「駐車禁止」です。","id":"car06","mode":"car","o":["駐車禁止","駐停車禁止","車両進入禁止"],"q":"この標識の意味は？","sign":"parking"},{"a":1,"e":"青地に赤い縁と赤い×印の円形標識は「駐停車禁止」です。","id":"car07","mode":"car","o":["駐車禁止","駐停車禁止","徐行"],"q":"この標識の意味は？","sign":"nostop"},{"a":0,"e":"赤い円に白い横棒の標識は「車両進入禁止」です。","id":"car08","mode":"car","o":["車両進入禁止","一方通行","通行止め解除"],"q":"この標識の意味は？","sign":"noentry"},{"a":1,"e":"赤い逆三角形に「止まれ」と表示された標識は「一時停止」です。","id":"car09","mode":"car","o":["徐行","一時停止","優先道路"],"q":"この標識の意味は？","sign":"stop"},{"a":1,"e":"赤い円で囲まれた数字は指定最高速度を示します。","id":"car10","mode":"car","o":["最低速度30km/h","最高速度30km/h","30m先工事"],"q":"この標識の意味は？","sign":"speed30"},{"a":0,"e":"青い長方形に白い矢印の標識は「一方通行」です。","id":"car11","mode":"car","o":["一方通行","直進禁止","指定方向外進行禁止"],"q":"この標識の意味は？","sign":"oneway"},{"a":2,"e":"駐停車禁止は、法令上の例外を除き、駐車も停車も禁止する規制です。","id":"car12","mode":"car","o":["駐車だけ","停車だけ","駐車も停車も"],"q":"駐停車禁止の場所では、原則としてできないのは？"},{"a":0,"e":"駐車禁止は駐車を禁止する規制です。赤信号や危険防止による停止は通常の駐車とは異なります。","id":"car13","mode":"car","o":["駐車","赤信号による停止","危険防止のための一時停止"],"q":"駐車禁止の場所で原則禁止されるのは？"},{"a":1,"e":"標識に付された「8-20」は、その規制が8時から20時まで行われることを示す例です。","id":"car14","mode":"car","o":["8月20日","8時から20時まで","8分から20分まで"],"q":"駐車禁止・駐停車禁止標識に「8-20」と数字が付いている場合、何を示す？"},{"a":1,"e":"横断歩道・自転車横断帯とその端から前後5m以内は、原則として駐停車禁止です。","id":"car15","mode":"car","o":["3m","5m","10m"],"q":"横断歩道の端から前後何m以内は、原則として駐車も停車も禁止？"},{"a":0,"e":"交差点の側端から5m以内は原則として駐停車禁止です。","id":"car16","mode":"car","o":["5m","10m","20m"],"q":"交差点の側端から何m以内は、原則として駐停車禁止？"},{"a":0,"e":"道路の曲がり角から5m以内は原則として駐停車禁止です。","id":"car17","mode":"car","o":["5m","10m","15m"],"q":"道路の曲がり角から何m以内は、原則として駐停車禁止？"},{"a":1,"e":"踏切とその前後10m以内は原則として駐停車禁止です。","id":"car18","mode":"car","o":["5m","10m","20m"],"q":"踏切とその前後何m以内は、原則として駐停車禁止？"},{"a":1,"e":"バス停等の標示位置から10m以内は、運行時間中、原則として駐停車禁止です。","id":"car19","mode":"car","o":["5m","10m","20m"],"q":"バス停の標示柱・標示板から何m以内は、運行時間中は原則として駐停車禁止？"},{"a":1,"e":"横断歩道では歩行者優先です。横断しようとする歩行者がいる場合は直前で一時停止して進路を譲ります。","id":"car20","mode":"car","o":["徐行して先に通る","一時停止して歩行者に進路を譲る","クラクションで知らせて通る"],"q":"横断歩道に横断しようとしている歩行者がいるとき、車はどうする？"},{"a":1,"e":"歩行者がいないことが明らかな場合を除き、横断歩道直前で停止できる速度で進行する必要があります。","id":"car21","mode":"car","o":["そのままの速度で通過","横断歩道直前で停止できる速度で進行","必ず30km/hまで加速"],"q":"横断歩道に接近するとき、歩行者がいないことが明らかでない場合は？"},{"a":0,"e":"横断歩道等とその手前30m以内では、他の車を追い越したり追い抜いたりしてはいけません。","id":"car22","mode":"car","o":["追い越し・追い抜き","左折","停止線での停止"],"q":"横断歩道や自転車横断帯とその手前から30m以内では、原則禁止される行為は？"},{"a":1,"e":"停止線がある場合は、その停止線の直前で一時停止します。","id":"car23","mode":"car","o":["交差点の中央","停止線の直前","標識の10m手前"],"q":"「止まれ」の標識がある交差点では、停止線がある場合どこで一時停止する？"},{"a":0,"e":"赤信号や危険防止のための一時停止は、通常の駐車・停車規制とは別に扱われます。","id":"car24","mode":"car","o":["原則ならない","必ずなる","夜間だけなる"],"q":"赤信号で停止することは「駐停車禁止違反」になる？"},{"a":0,"e":"一定の許可要件を満たし警察署長の駐車許可を受けた場合、駐車できることがあります。自動的に認められるわけではありません。","id":"car25","mode":"car","o":["ある","絶対にない","営業車だけ自動的に可能"],"q":"駐車禁止規制がある場所でも、特別な事情があり警察署長の駐車許可を受ければ駐車できる場合がある？"},{"a":1,"e":"業務中という理由だけで駐車禁止が解除されるわけではありません。必要に応じて駐車許可制度の対象となる場合があります。","id":"car26","mode":"car","o":["はい","いいえ","ハザードを点ければ合法"],"q":"配送・訪問作業中なら、駐車禁止場所に許可なく駐車しても必ず合法になる？"},{"a":1,"e":"運転中の携帯電話使用等は危険で、道路交通法上の禁止・罰則対象です。"