:"学校周辺では子どもの急な横断や飛び出しを想定して走ります。","id":"bike102","mode":"bike","o":["子どもの飛び出しを予測して速度を落とす","普段通り高速で走る","ベルを鳴らし続ける"],"q":"学校の門の前を下校時間に通る。どうする？"},{"a":0,"e":"視界を遮る車両の陰から人や車が出る可能性があります。","id":"bike103","mode":"bike","o":["十分減速して安全を確認する","止まっているトラックを利用して一気に進む","反対車線へ大きく出る"],"q":"交差点の角にトラックが止まって視界が悪い。どうする？"},{"a":0,"e":"下り坂では速度が上がり停止距離も伸びるため、交差点より前に減速します。","id":"bike104","mode":"bike","o":["止まりきれない可能性","速度が高いほど安全","交差点では自転車が必ず優先"],"q":"坂道の下で交差点がある。速度が出ているときの危険は？"},{"a":0,"e":"夕暮れは視認性が急に落ちます。早めのライト点灯で自分の存在を知らせます。","id":"bike105","mode":"bike","o":["早めに点灯する","完全に暗くなるまで点けない","街灯があれば不要"],"q":"夕暮れ時、まだ少し明るい。ライトはどうする？"},{"a":0,"e":"歩行者が周囲に気づかず進路を変える可能性があります。十分な距離を取ります。","id":"bike106","mode":"bike","o":["急な進路変更を予測して距離を取る","真横を高速で抜く","ベルで驚かせる"],"q":"前方の歩行者がスマホを見ながら歩いている。自転車でどうする？"},{"a":0,"e":"狭い場所では互いの動きを確認し、必要なら停止して安全にすれ違います。","id":"bike107","mode":"bike","o":["速度を落として安全な間隔ですれ違う","どちらも加速する","中央を譲らず進む"],"q":"狭い道で対向自転車が来た。最も安全なのは？"},{"a":0,"e":"大型車の後方では視界が悪く、急ブレーキにも対応しづらいため車間を取ります。","id":"bike108","mode":"bike","o":["前方視界が遮られ急停止にも対応しにくい","空気抵抗が減るので常に安全","信号確認が不要になる"],"q":"トラックやバスの後ろを至近距離で走る危険は？"},{"a":0,"e":"片手運転は操作性を低下させ、風でバランスを崩す危険があります。地域の規則にも注意します。","id":"bike109","mode":"bike","o":["操作が不安定になり危険","両手運転より安全","風が強いほど安定する"],"q":"雨の日、傘を差しながら片手で自転車を運転するのは？"},{"a":0,"e":"自分がルールを守るだけでなく、周囲のミスや見えない危険まで予測することが事故防止につながります。","id":"bike110","mode":"bike","o":["『見えていない所から何か出るかも』と先を読む","自分がルールを守っていれば周囲は見なくてよい","ベルを鳴らせば危険はなくなる"],"q":"自転車の危険予知で最も大切なのは？"}]$bank$::jsonb) item;

-- Private definer is necessary to read hidden answers and atomically award points.
create function app_private.start_quiz(p_mode text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
 u uuid := auth.uid(); qs jsonb; q jsonb; options jsonb; answer integer;
 arranged jsonb := '[]'; sid uuid := gen_random_uuid();
begin
 if u is null then raise exception 'authentication_required' using errcode='28000'; end if;
 if not public.is_user_active(u) then raise exception 'account_suspended' using errcode='42501'; end if;
 if p_mode is null or p_mode not in ('car','bike','mix') then raise exception 'invalid_quiz_mode' using errcode='22023'; end if;
 perform pg_advisory_xact_lock(hashtextextended('quiz:'||u::text,0));
 with unique_questions as (
  select distinct on (regexp_replace(body->>'q','\s','','g')) mode,body
  from app_private.quiz_questions
  where p_mode='mix' or mode=p_mode
  order by regexp_replace(body->>'q','\s','','g'),id
 ), ranked as (
  select body,row_number() over(partition by mode order by random()) as rn from unique_questions
 )
 select jsonb_agg(body order by random()) into qs from ranked
 where rn<=case when p_mode='mix' then 5 else 10 end;
 if jsonb_array_length(qs) is distinct from 10 then raise exception 'quiz_bank_unavailable'; end if;
 for q in select value from jsonb_array_elements(qs) loop
  select jsonb_agg(value order by pos), max(pos::integer-1) filter(where original=(q->>'a')::integer+1)
  into options,answer from (
   select value,ordinality as original,row_number() over(order by random()) as pos
   from jsonb_array_elements(q->'o') with ordinality
  ) shuffled;
  arranged:=arranged||jsonb_build_array(jsonb_set(jsonb_set(q,'{o}',options),'{a}',to_jsonb(answer)));
 end loop;
 insert into app_private.quiz_sessions(user_id,id,questions) values(u,sid,arranged)
 on conflict(user_id) do update set id=excluded.id,questions=excluded.questions,responses='[]',score=0,created_at=now();
 return jsonb_build_object('session_id',sid,'index',0,'question',(arranged->0)-'a'-'e');
end $$;

create function app_private.answer_quiz(p_session_id uuid,p_index integer,p_choice integer) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
 u uuid:=auth.uid(); s app_private.quiz_sessions%rowtype; q jsonb; r jsonb;
 n integer; correct boolean; points integer:=0; bal integer; claimed boolean:=false;
 d date:=(timezone('Asia/Tokyo',now()))::date;
begin
 if u is null then raise exception 'authentication_required' using errcode='28000'; end if;
 if not public.is_user_active(u) then raise exception 'account_suspended' using errcode='42501'; end if;
 if p_index is null or p_index<0 or p_index>9 or p_choice is null then
  raise exception 'invalid_quiz_answer' using errcode='22023';
 end if;
 perform pg_advisory_xact_lock(hashtextextended('quiz:'||u::text,0));
 select * into s from app_private.quiz_sessions where user_id=u and id=p_session_id for update;
 if not found then raise exception 'quiz_session_not_found'; end if;
 n:=jsonb_array_length(s.responses);
 -- Exact retries return the original receipt, including the final points receipt.
 if p_index<n then
  r:=s.responses->p_index;
  if (r->>'choice')::integer is distinct from p_choice then raise exception 'quiz_answer_locked'; end if;
  return r;
 end if;
 if s.created_at<now()-interval '2 hours' then raise exception 'quiz_session_expired'; end if;
 if p_index<>n then raise exception 'quiz_answer_out_of_order'; end if;
 q:=s.questions->n;
 if p_choice<0 or p_choice>=jsonb_array_length(q->'o') then raise exception 'invalid_quiz_answer' using errcode='22023'; end if;
 correct:=p_choice=(q->>'a')::integer;
 s.score:=s.score+case when correct then 1 else 0 end;
 if n=9 then
  insert into public.quiz_claims(user_id,claim_date,score) values(u,d,s.score)
  on conflict(user_id,claim_date) do nothing;
  claimed:=not found;
  if not claimed then points:=s.score; end if;
  if points>0 then bal:=public.apply_point_transaction(u,points,'quiz',d::text);
  else select coalesce(point,0) into bal from public.profiles where auth_id=u; end if;
 end if;
 r:=jsonb_build_object('index',n,'choice',p_choice,'correct',correct,'answer',(q->>'a')::integer,
  'explanation',q->>'e','score',s.score,'complete',n=9,
  'next_question',case when n<9 then (s.questions->(n+1))-'a'-'e' else null end,
  'awarded',points,'balance',bal,'already_claimed',claimed);
 update app_private.quiz_sessions set responses=responses||jsonb_build_array(r),score=s.score where user_id=u;
 return r;
end $$;

create function public.start_quiz(p_mode text) returns jsonb
language sql security invoker set search_path = '' as $$
 select app_private.start_quiz(p_mode);
$$;
create function public.answer_quiz(p_session_id uuid,p_index integer,p_choice integer) returns jsonb
language sql security invoker set search_path = '' as $$
 select app_private.answer_quiz(p_session_id,p_index,p_choice);
$$;
revoke all on function app_private.start_quiz(text),app_private.answer_quiz(uuid,integer,integer),
 public.start_quiz(text),public.answer_quiz(uuid,integer,integer) from public,anon,authenticated;
grant usage on schema app_private to authenticated;
grant execute on function app_private.start_quiz(text),app_private.answer_quiz(uuid,integer,integer),
 public.start_quiz(text),public.answer_quiz(uuid,integer,integer) to authenticated;

-- Retire the client-score endpoint, including stale pages.
revoke all on function public.claim_quiz_points(integer) from public,anon,authenticated;
